-- Bangkok places to hang out, from OpenStreetMap (© OpenStreetMap contributors, ODbL), for the Hangout map.
-- Generated from an Overpass query inside the Bangkok box (13.45–14.10 N, 100.25–100.95 E), named places only,
-- private ones left out:
--   tourism=attraction|museum|gallery|viewpoint|zoo|aquarium|theme_park
--   leisure=park|garden|nature_reserve|water_park|bowling_alley|escape_game|ice_rink|amusement_arcade|miniature_golf
--   shop=mall|department_store (kind "mall"), amenity=marketplace (kind "market")|cinema|theatre|arts_centre,
--   amenity=place_of_worship + religion=buddhist (kind "temple"), historic=monument|palace|fort|castle
-- 2810 places: temple 863, park 376, market 355, mall 330, attraction 267, garden 179, museum 153, monument 62, castle 51, gallery 43, cinema 33, theatre 30, viewpoint 17, amusement_arcade 14, arts_centre 11, zoo 9, theme_park 7, fort 3, escape_game 2, water_park 2, aquarium 1, ice_rink 1, miniature_golf 1.
-- Safe to re-run: existing places (including food places with the same OpenStreetMap id) are left as they are.

on conflict (osm_type, osm_id) do nothing;
